from pathlib import Path
p=Path('worker/ai/llm.ts');s=p.read_text(encoding='utf8')
s += '''\nexport type StreamResult={stream:ReadableStream<Uint8Array>;cancel:()=>void};\nexport async function callStream(env:Env,messages:{role:string;content:string}[],maxTokens=900,signal?:AbortSignal){\n const started=performance.now();let attempts=0;\n for(let attempt=0;attempt<2;attempt++){attempts=attempt+1;\n  try{const response=await fetch(env.AI_GATEWAY_URL!,{method:'POST',signal:signal||AbortSignal.timeout(30000),headers:{'content-type':'application/json',authorization:`Bearer ${env.AI_GATEWAY_TOKEN}`},body:JSON.stringify({model:env.AI_MODEL||'qwen-plus',messages,max_tokens:maxTokens,temperature:0.65,enable_thinking:false,response_format:{type:'json_object'},stream:true})});\n   if(!response.ok||!response.body){console.error(JSON.stringify({event:'llm_stream_failure',status:response.status,attempt}));if(response.status<500&&response.status!==429)break;continue;}\n   console.log(JSON.stringify({event:'llm_stream_open',elapsed_ms:Math.round(performance.now()-started),attempts}));\n   return response.body;\n  }catch(error){console.error(JSON.stringify({event:'llm_stream_exception',attempt,type:error instanceof Error?error.name:'unknown'}));}\n }\n throw new Error('语言服务暂时不可用');\n}\n'''
p.write_text(s,encoding='utf8')
Path('worker/ai/streamService.ts').write_text('''import type {Env} from '../index';\nimport type {Profile,Message} from './types';\nimport {analyzeEmotion} from './emotionAnalyzer';\nimport {updateRelationship} from './relationshipManager';\nimport {buildPrompt} from './promptBuilder';\nimport {loadMemory,saveTurn,saveSummary} from './memoryManager';\nimport {callStream} from './llm';\n\nconst encoder=new TextEncoder();\nconst event=(type:string,data:unknown)=>encoder.encode(`event: ${type}\\ndata: ${JSON.stringify(data)}\\n\\n`);\nfunction partialReply(raw:string){\n const match=raw.match(/"replyEn"\\s*:\\s*"((?:\\\\.|[^"\\\\])*)/);if(!match)return '';\n try{return JSON.parse(`"${match[1]}"`)}catch{return match[1].replace(/\\\\n/g,'\\n').replace(/\\\\"/g,'"');}\n}\nfunction parseDelta(value:any){const content=value?.choices?.[0]?.delta?.content;return typeof content==='string'?content:'';}\nexport async function chatStreamService(env:Env,body:{userId:string;requestId:string;message:string;setup:Profile;history?:Message[]},requestSignal?:AbortSignal){\n if(!env.DB)throw new Error('数据库未配置');\n const cached=await env.DB.prepare('SELECT response_json FROM chat_requests WHERE user_id=? AND request_id=?').bind(body.userId,body.requestId).first<{response_json:string}>();\n if(cached){const result=JSON.parse(cached.response_json);return new ReadableStream({start(controller){controller.enqueue(event('delta',{text:result.replyEn}));controller.enqueue(event('done',{result}));controller.close();}});}\n const started=performance.now();const memory=await loadMemory(env.DB,body.userId);const profile=memory.state?.profile_completed?JSON.parse(memory.state.profile_json):body.setup;const emotion=analyzeEmotion(body.message);const relationship=updateRelationship(memory.state,new Date().toISOString());\n let summary=memory.summary;const total=memory.state?.message_count||0;\n if(total-(memory.state?.summary_through||0)>=40){try{const summaryMessages=[{role:'system',content:'把对话压缩为事实摘要，只返回JSON {"summary":"..."}。保留用户正在做什么、待发生事件、未完话题、角色答应继续聊的事；禁止虚构。'},{role:'user',content:JSON.stringify({previous:summary,messages:memory.messages})}];const summaryStream=await (async()=>{const {callJson}=await import('./llm');return callJson(env,summaryMessages,600)})();if(typeof summaryStream.summary==='string'){summary=summaryStream.summary;await saveSummary(env.DB,body.userId,summary,total);}}catch{console.error(JSON.stringify({event:'summary_failed'}));}}\n const history=memory.messages.length?memory.messages:(body.history||[]).slice(-40);const systemPrompt=buildPrompt(profile,emotion,relationship,summary);const upstream=await callStream(env,[{role:'system',content:systemPrompt},...history.map((m:any)=>({role:m.role,content:m.timestamp?`[${m.timestamp}] ${m.content}`:m.content})),{role:'user',content:body.message}],900,requestSignal);\n const reader=upstream.getReader();const decoder=new TextDecoder();let buffer='';let raw='';let reply='';let firstMs:number|null=null;let usage:any=null;let closed=false;\n return new ReadableStream({async start(controller){\n  try{while(true){const part=await reader.read();if(part.done)break;buffer+=decoder.decode(part.value,{stream:true});const lines=buffer.split(/\\r?\\n/);buffer=lines.pop()||'';for(const line of lines){if(!line.startsWith('data:'))continue;const data=line.slice(5).trim();if(!data||data==='[DONE]')continue;let value:any;try{value=JSON.parse(data)}catch{continue;}usage=value.usage||usage;const delta=parseDelta(value);if(!delta)continue;raw+=delta;const next=partialReply(raw);if(next.length>reply.length){reply=next;if(firstMs===null){firstMs=Math.round(performance.now()-started);console.log(JSON.stringify({event:'stream_timing',ttft_ms:firstMs,history_messages:history.length}));}controller.enqueue(event('delta',{text:reply.slice(reply.length-(next.length-reply.length))}));}}}const finalMatch=raw.match(/\\{[\\s\\S]*\\}/);let result:any;try{result=finalMatch?JSON.parse(finalMatch[0]):null}catch{result=null;}if(!result||typeof result.replyEn!=='string'||!result.replyEn.trim())throw new Error('流式回复不完整');const normalized={hasError:false,errorLevel:'none',original:body.message,corrected:body.message,explanationZh:'',requireRepeat:false,replyZh:'',...result};await saveTurn(env.DB,body.userId,profile,relationship,body.message,normalized,emotion,body.requestId);console.log(JSON.stringify({event:'stream_timing',ttft_ms:firstMs,complete_ms:Math.round(performance.now()-started),input_tokens:usage?.prompt_tokens??null,output_tokens:usage?.completion_tokens??null,llm_calls:1,saved:true}));controller.enqueue(event('done',{result:normalized}));controller.close();closed=true;}catch(error){console.error(JSON.stringify({event:'stream_failed',message:error instanceof Error?error.message:'unknown',saved:false}));if(!closed){controller.enqueue(event('error',{message:'流式回复中断，请重试'}));controller.close();closed=true;}}},cancel(){reader.cancel().catch(()=>{});}});\n}\n''',encoding='utf8')
